'use client';

import { useRef, type CSSProperties, type ElementType } from 'react';
import { usePlayback } from './use-playback';
import './gradient-sweep-text.css';

export interface GradientSweepTextProps {
  text: string;
  as?: ElementType;
  /** One pass of the color band, in milliseconds. */
  duration?: number;
  direction?: 'left' | 'right';
  paused?: boolean;
  className?: string;
}

/**
 * A band of color crosses stationary lettering. The solid base text keeps
 * full contrast underneath; the band is a decorative copy on top.
 */
export function GradientSweepText({
  text,
  as: Tag = 'span',
  duration = 2600,
  direction = 'right',
  paused = false,
  className = '',
}: GradientSweepTextProps) {
  const root = useRef<HTMLElement>(null);
  const playing = usePlayback(root, paused);
  return (
    <Tag
      ref={root}
      className={`mg-sweeptext ${className}`}
      data-playing={playing}
      data-direction={direction}
      style={{ '--mg-duration': `${duration}ms` } as CSSProperties}
    >
      {text}
      <span className='mg-sweeptext__band' aria-hidden='true'>
        {text}
      </span>
    </Tag>
  );
}

.mg-sweeptext {
  position: relative;
  display: inline-block;
  margin: 0;
  color: var(--mg-text, #ffffff);
}

.mg-sweeptext__band {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 0 38%,
    var(--mg-accent, #eaf2fb) 45%,
    #eaf2fb 50%,
    var(--mg-accent, #eaf2fb) 55%,
    transparent 62% 100%
  );
  background-size: 300% 100%;
  background-position: 100% 0;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  pointer-events: none;
}

.mg-sweeptext[data-playing='true'] .mg-sweeptext__band {
  animation: mg-sweeptext-right var(--mg-duration) linear infinite;
}

.mg-sweeptext[data-playing='true'][data-direction='left'] .mg-sweeptext__band {
  animation-direction: reverse;
}

@keyframes mg-sweeptext-right {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

/* Still: a fixed two-tone treatment instead of a moving band. */
@media (prefers-reduced-motion: reduce) {
  .mg-sweeptext__band {
    display: none;
  }
  .mg-sweeptext {
    color: var(--mg-accent-text, #dce9f7);
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
